import numpy as np


def neuron_model(theta, level_1=0.0, shift_1=0.0, scale_1=1.0, pref_1=3.141592653589793, width_1=1.0, exponent_1=2.0, opposite_1=0.0, shift_2=0.0, exponent_2=2.0):
    level_1 = np.clip(level_1, 0.0, 100.0)
    shift_1 = np.clip(shift_1, -100.0, 100.0)
    scale_1 = np.clip(scale_1, 0.0, 100.0)
    pref_1 = np.clip(pref_1, 0.0, 6.283185307179586)
    width_1 = np.clip(width_1, 0.01, 10.0)
    exponent_1 = np.clip(exponent_1, 0.1, 8.0)
    opposite_1 = np.clip(opposite_1, 0.0, 100.0)
    shift_2 = np.clip(shift_2, -100.0, 100.0)
    exponent_2 = np.clip(exponent_2, 0.1, 8.0)

    def _div(a, b):
        return a / np.where(np.abs(b) < 1e-6, np.where(b < 0, -1e-6, 1e-6), b)

    def _pow(a, b):
        return (np.abs(a) + 1e-12) ** np.clip(b, -8.0, 8.0)

    def _exp(a):
        return np.exp(np.clip(a, -50.0, 50.0))

    def _wrap(a):
        return np.arctan2(np.sin(a), np.cos(a))

    return (((level_1 + shift_1) + (scale_1 * _exp((-0.5 * _pow(_div(np.abs(_wrap((theta - pref_1))), width_1), exponent_1))))) + (opposite_1 * _exp((-0.5 * _pow(_div(np.abs(_wrap((theta - ((pref_1 + 3.141592653589793) - shift_2)))), width_1), exponent_2))))) + 0.0 * theta
